    "misc.docsTitle":"Docs",
    "misc.docsP1":"<strong style=\"color:var(--ink)\">How YOYOPDF works.</strong> Pick a tool from the header, the left-side dock, or the tools grid on the homepage. Drop in a file (or click to browse), adjust that tool's options if it has any, then download the result — every step runs locally in your browser, so nothing is ever uploaded.",
    "misc.docsP2":"Page-based tools (Reorder, Delete, Extract, Add Blank Page, Organize) show every page as a thumbnail: click to select, drag to reorder, or use the small rotate/delete controls on a thumbnail directly. A page-range field (e.g. <code>1,3,5-8</code>) is also available wherever you need to select many pages at once.",
    "misc.docsP3Pre":"Nothing here requires an account or a subscription. If a tool doesn't behave the way you expect, the",
    "misc.docsP3Post":"page reaches us directly.",

    "misc.contactEyebrow":"GET IN TOUCH",
