    "misc.docsTitle":"दस्तावेज़ीकरण",
    "misc.docsP1":"<strong style=\"color:var(--ink)\">YOYOPDF कैसे काम करता है।</strong> हेडर, बाईं ओर के डॉक, या होमपेज पर टूल्स ग्रिड से एक टूल चुनें। एक फ़ाइल छोड़ें (या ब्राउज़ करने के लिए क्लिक करें), यदि उस टूल के विकल्प हैं तो उन्हें समायोजित करें, फिर परिणाम डाउनलोड करें — हर चरण आपके ब्राउज़र में स्थानीय रूप से चलता है, इसलिए कुछ भी कभी अपलोड नहीं होता।",
    "misc.docsP2":"पेज-आधारित टूल (पुनर्व्यवस्थित करें, हटाएं, निकालें, खाली पेज जोड़ें, व्यवस्थित करें) हर पेज को थंबनेल के रूप में दिखाते हैं: चुनने के लिए क्लिक करें, पुनर्व्यवस्थित करने के लिए खींचें, या सीधे थंबनेल पर छोटे रोटेट/डिलीट नियंत्रणों का उपयोग करें। एक पेज-रेंज फ़ील्ड (जैसे <code>1,3,5-8</code>) भी उपलब्ध है जहां भी आपको एक साथ कई पेज चुनने की आवश्यकता हो।",
    "misc.docsP3Pre":"यहां किसी खाते या सदस्यता की आवश्यकता नहीं है। यदि कोई टूल आपकी अपेक्षा के अनुसार व्यवहार नहीं करता है, तो",
    "misc.docsP3Post":"पेज सीधे हम तक पहुंचता है।",

