    "misc.docsTitle":"Documentación",
    "misc.docsP1":"<strong style=\"color:var(--ink)\">Cómo funciona YOYOPDF.</strong> Elige una herramienta desde el encabezado, el panel lateral o la cuadrícula de herramientas de la página principal. Suelta un archivo (o haz clic para explorar), ajusta las opciones de esa herramienta si las tiene, y luego descarga el resultado — cada paso se ejecuta localmente en tu navegador, así que nada se sube nunca.",
    "misc.docsP2":"Las herramientas basadas en páginas (Reordenar, Eliminar, Extraer, Añadir página en blanco, Organizar) muestran cada página como una miniatura: haz clic para seleccionar, arrastra para reordenar, o usa los pequeños controles de rotar/eliminar directamente en una miniatura. También hay disponible un campo de rango de páginas (p. ej. <code>1,3,5-8</code>) siempre que necesites seleccionar varias páginas a la vez.",
    "misc.docsP3Pre":"Nada aquí requiere una cuenta ni una suscripción. Si una herramienta no se comporta como esperas, la página de",
    "misc.docsP3Post":"nos contacta directamente.",

