    "misc.docsP1":"<strong style=\"color:var(--ink)\">Comment fonctionne YOYOPDF.</strong> Choisissez un outil depuis l'en-tête, le dock latéral gauche, ou la grille d'outils de la page d'accueil. Déposez un fichier (ou cliquez pour parcourir), ajustez les options de cet outil s'il en a, puis téléchargez le résultat — chaque étape s'exécute localement dans votre navigateur, donc rien n'est jamais téléversé.",
