    "misc.docsTitle":"Dokumentation",
    "misc.docsP1":"<strong style=\"color:var(--ink)\">So funktioniert YOYOPDF.</strong> Wähle ein Werkzeug aus der Kopfzeile, der linken Seitenleiste oder dem Werkzeugraster auf der Startseite. Lege eine Datei hinein (oder klicke zum Durchsuchen), passe die Optionen dieses Werkzeugs an, falls vorhanden, und lade dann das Ergebnis herunter — jeder Schritt läuft lokal in deinem Browser ab, sodass nie etwas hochgeladen wird.",
    "misc.docsP2":"Seitenbasierte Werkzeuge (Neu anordnen, Löschen, Extrahieren, Leere Seite hinzufügen, Organisieren) zeigen jede Seite als Miniaturansicht: klicke zum Auswählen, ziehe zum Neuanordnen oder verwende die kleinen Dreh-/Löschsteuerelemente direkt an einer Miniaturansicht. Ein Seitenbereichsfeld (z. B. <code>1,3,5-8</code>) steht auch überall dort zur Verfügung, wo du mehrere Seiten auf einmal auswählen musst.",
    "misc.docsP3Pre":"Nichts hier erfordert ein Konto oder ein Abonnement. Wenn sich ein Werkzeug nicht wie erwartet verhält, erreicht dich die",
    "misc.docsP3Post":"Seite uns direkt.",

