    "misc.docsTitle":"Documentação",
    "misc.docsP1":"<strong style=\"color:var(--ink)\">Como o YOYOPDF funciona.</strong> Escolha uma ferramenta no cabeçalho, na barra lateral esquerda ou na grade de ferramentas da página inicial. Solte um arquivo (ou clique para procurar), ajuste as opções dessa ferramenta se houver, e depois baixe o resultado — cada etapa é executada localmente no seu navegador, então nada é enviado.",
    "misc.docsP2":"As ferramentas baseadas em páginas (Reordenar, Excluir, Extrair, Adicionar página em branco, Organizar) mostram cada página como uma miniatura: clique para selecionar, arraste para reordenar, ou use os pequenos controles de girar/excluir diretamente em uma miniatura. Um campo de intervalo de páginas (ex.: <code>1,3,5-8</code>) também está disponível sempre que você precisar selecionar várias páginas de uma vez.",
    "misc.docsP3Pre":"Nada aqui requer uma conta ou assinatura. Se uma ferramenta não se comportar como esperado, a página de",
    "misc.docsP3Post":"nos alcança diretamente.",

    "misc.contactEyebrow":"ENTRE EM CONTATO",
    "misc.contactHeroTitle":"Como podemos ajudar?",
