    "misc.docsTitle":"ドキュメント",
    "misc.docsP1":"<strong style=\"color:var(--ink)\">YOYOPDFの使い方。</strong> ヘッダー、左側のドック、またはホームページのツールグリッドからツールを選択します。ファイルをドロップ（またはクリックして参照）し、そのツールにオプションがあれば調整してから、結果をダウンロードします — すべての手順はブラウザ内でローカルに実行されるため、何もアップロードされません。",
    "misc.docsP2":"ページベースのツール（並べ替え、削除、抽出、白紙ページの追加、整理）では、すべてのページがサムネイルとして表示されます。クリックして選択、ドラッグして並べ替え、またはサムネイル上の小さな回転/削除コントロールを直接使用できます。複数のページを一度に選択する必要がある場所では、ページ範囲フィールド（例: <code>1,3,5-8</code>）も使用できます。",
    "misc.docsP3Pre":"ここではアカウントやサブスクリプションは一切必要ありません。ツールが期待どおりに動作しない場合は、",
    "misc.docsP3Post":"ページから直接ご連絡ください。",

