    "about.why1Title":"기본적으로 비공개", "about.why1Desc":"파일이 기기를 벗어나는 일은 없습니다. 모든 작업은 브라우저 내에서 로컬로 이루어집니다.",
    "about.why2Title":"설치 불필요", "about.why2Desc":"다운로드도, 설치 프로그램도 필요 없습니다. 그냥 열고 바로 시작하세요.",
    "about.why3Title":"모든 필수 도구", "about.why3Desc":"병합, 분할, 변환, 압축, 서명, 편집 등등.",
    "about.why4Title":"간단하고 안정적", "about.why4Desc":"모든 작업에서 편리한 브라우저 기반 처리를 위해 설계되었습니다.",
    "about.why5Title":"언제나 무료", "about.why5Desc":"가입도, 제한도, 약정도 없이 완전히 무료입니다.",
    "about.ctaHeading":"이제", "about.ctaAccent":"PDF 작업을 시작해볼까요?",
    "about.ctaText":"아래 도구 중 아무거나 바로 사용해보세요 — 가입도, 업로드도, 대기도 필요 없습니다.",
