    "privacy.metaUpdated":"최종 업데이트: 2026년",
    "privacy.headingLine1":"당신의", "privacy.headingAccent1":"프라이버시.",
    "privacy.headingLine2":"우리의", "privacy.headingAccent2":"약속.",
    "privacy.paragraph":"YOYOPDF의 모든 PDF 및 이미지 도구는 전적으로 브라우저 내에서 작동합니다. 저희는 사용자의 파일을 업로드, 저장, 공유하지 않습니다.",
    "privacy.feature1Title":"100% 로컬 처리", "privacy.feature1Desc":"모든 작업이 사용자의 기기에서 이루어집니다.",
    "privacy.feature2Title":"업로드 없음", "privacy.feature2Desc":"파일을 어디로도 전송하지 않습니다.",
    "privacy.feature3Title":"추적 없음", "privacy.feature3Desc":"분석, 쿠키, 사용자 프로파일링이 전혀 없습니다.",
    "privacy.nodeLocal":"로컬 처리", "privacy.nodeNoUploads":"업로드 없음",
    "privacy.nodeNoTracking":"추적 없음", "privacy.nodeControl":"당신이 통제합니다",
    "privacy.principle1":"100% 로컬 처리", "privacy.principle2":"업로드 없음", "privacy.principle3":"추적 없음",
    "privacy.principle4":"데이터 판매 없음", "privacy.principle5":"당신이 통제합니다",
    "privacy.sectionOverview":"개요",
    "privacy.overviewBody":"사용자의 파일이 기기를 벗어나는 일은 결코 없습니다. YOYOPDF의 모든 PDF 및 이미지 도구는 자바스크립트를 사용해 브라우저에서 작동합니다 — 어떤 것도 서버에 업로드, 저장, 전송되지 않습니다. 저희는 추적 쿠키를 사용하지 않으며 개인 데이터를 판매하지도 않습니다.",
    "privacy.sectionProcessing":"파일 및 로컬 처리",
    "privacy.processingBody":"YOYOPDF의 모든 PDF 및 이미지 도구는 자바스크립트를 사용해 브라우저에서 작동합니다 — 어떤 것도 서버에 업로드, 저장, 전송되지 않습니다.",
    "privacy.sectionAnalytics":"분석",
    "privacy.analyticsBody":"이 사이트에 표시된 신뢰 배지는 도구가 실제로 작동하는 방식을 설명하는 것입니다 — 방문자 카운터나 추적기가 아닙니다.",
    "privacy.sectionCookies":"쿠키",
    "privacy.cookiesBody":"저희는 추적 쿠키를 사용하지 않으며 개인 데이터를 판매하지도 않습니다.",
    "privacy.sectionContact":"문의",
    "privacy.contactBody":"문의 양식을 사용하시면 입력하신 정보는 사용자 본인의 메일 클라이언트를 통해 저희 이메일로 직접 전송됩니다 — 다른 곳에는 저장되지 않습니다.",

    "terms.badge":"이용약관", "terms.heading":"서비스 이용약관",
    "terms.subheading":"YOYOPDF 이용을 위한 간단하고 투명한 약관입니다.", "terms.metaUpdated":"최종 업데이트: 2026년",
    "terms.navUsing":"YOYOPDF 이용", "terms.navResponsibilities":"사용자 책임",
    "terms.navDisclaimers":"면책 조항 및 책임 제한", "terms.navChanges":"약관 변경", "terms.navContact":"문의",
    "terms.calloutIntro":"YOYOPDF를 이용하기 전에 이 약관을 주의 깊게 읽어주세요.",
    "terms.card1Title":"책임감 있게 사용하세요", "terms.card1Desc":"서비스를 방해하거나, 대규모로 스크래핑하거나, 불법적으로 사용하지 마세요.",
    "terms.card2Title":"백업을 유지하세요", "terms.card2Desc":"파일 처리 전 백업을 유지하는 것은 사용자의 책임입니다.",
    "terms.card3Title":"있는 그대로 제공", "terms.card3Desc":"무료로, \"있는 그대로\", 어떠한 보증도 없이 제공됩니다.",
    "terms.sectionUsing":"YOYOPDF 이용", "terms.usingBody":"YOYOPDF는 개인 또는 상업적 용도로 이용하실 수 있습니다.",
    "terms.sectionResponsibilities":"사용자 책임",
    "terms.responsibilitiesBody":"모든 도구가 테스트되었지만, 중요한 파일을 처리하기 전 백업을 유지하는 것은 사용자의 책임입니다. 서비스를 방해하거나, 대규모로 스크래핑하거나, 불법적인 목적으로 사용하지 마시기 바랍니다.",
    "terms.sectionDisclaimers":"면책 조항 및 책임 제한",
    "terms.disclaimersBody":"YOYOPDF는 무료로, \"있는 그대로\", 어떠한 종류의 보증도 없이 제공됩니다.",
    "terms.sectionChanges":"약관 변경",
    "terms.changesBody":"새로운 도구가 추가됨에 따라 이 약관은 수시로 업데이트될 수 있습니다. 변경 후에도 사이트를 계속 이용하시면 업데이트된 약관에 동의하는 것으로 간주됩니다.",
    "terms.sectionContact":"문의",
    "terms.contactBody":"이 약관에 대해 궁금하신 점이 있나요? 언제든지 문의해 주시면 답변해 드리겠습니다.",
    "terms.ctaTitle":"이 약관에 대해 궁금하신 점이 있나요?", "terms.ctaSub":"직접 문의해 주세요.", "terms.ctaBtn":"문의하기 →",

