    "misc.docsTitle":"문서",
    "misc.docsP1":"<strong style=\"color:var(--ink)\">YOYOPDF 작동 방식.</strong> 헤더, 왼쪽 독, 또는 홈페이지의 도구 그리드에서 도구를 선택하세요. 파일을 놓거나(또는 클릭하여 찾아보기) 해당 도구에 옵션이 있으면 조정한 다음 결과를 다운로드하세요 — 모든 단계는 브라우저에서 로컬로 실행되므로 아무것도 업로드되지 않습니다.",
    "misc.docsP2":"페이지 기반 도구(재정렬, 삭제, 추출, 빈 페이지 추가, 정리)는 모든 페이지를 축소판으로 표시합니다: 클릭하여 선택, 드래그하여 재정렬하거나 축소판에서 직접 작은 회전/삭제 컨트롤을 사용하세요. 여러 페이지를 한 번에 선택해야 하는 경우 페이지 범위 필드(예: <code>1,3,5-8</code>)도 사용할 수 있습니다.",
    "misc.docsP3Pre":"여기에는 계정이나 구독이 필요하지 않습니다. 도구가 예상대로 작동하지 않으면,",
    "misc.docsP3Post":"페이지에서 저희에게 직접 연락하실 수 있습니다.",

