    "misc.docsTitle":"الوثائق",
    "misc.docsP1":"<strong style=\"color:var(--ink)\">كيف يعمل YOYOPDF.</strong> اختر أداة من الرأس، أو اللوحة الجانبية اليسرى، أو شبكة الأدوات في الصفحة الرئيسية. أفلت ملفًا (أو انقر للتصفح)، واضبط خيارات تلك الأداة إن وُجدت، ثم نزّل النتيجة — تعمل كل خطوة محليًا في متصفحك، لذا لا يتم رفع أي شيء مطلقًا.",
    "misc.docsP2":"تعرض الأدوات المعتمدة على الصفحات (إعادة الترتيب، الحذف، الاستخراج، إضافة صفحة فارغة، التنظيم) كل صفحة كصورة مصغّرة: انقر للتحديد، واسحب لإعادة الترتيب، أو استخدم عناصر التحكم الصغيرة للتدوير/الحذف مباشرةً على الصورة المصغّرة. يتوفر أيضًا حقل نطاق صفحات (مثال: <code>1,3,5-8</code>) أينما احتجت لتحديد عدة صفحات دفعة واحدة.",
